# use bevy_ecs::intern::*;
# use std::sync::Mutex;
#[derive(PartialEq, Eq, Hash, Debug)]
struct Value(i32);
impl Internable for Value {
    // ...
# fn leak(&self) -> &'static Self { Box::leak(Box::new(Value(self.0))) }
# fn ref_eq(&self, other: &Self) -> bool { std::ptr::eq(self, other ) }
# fn ref_hash<H: std::hash::Hasher>(&self, state: &mut H) { std::ptr::hash(self, state); }
}
let interner_1 = Interner::new();
let interner_2 = Interner::new();
// Even though both values are identical, their interned forms do not
// compare equal as they use different interner instances.
assert_ne!(interner_1.intern(&Value(42)), interner_2.intern(&Value(42)));
# // Store the interners inside a `static` so
# // that miri doesn't report them as a memory leak.
# static LEAKS: Mutex<Vec<Interner<Value>>> = Mutex::new(Vec::new());
# let mut leaks = LEAKS.lock().unwrap();
# leaks.push(interner_1);
# leaks.push(interner_2);

# use bevy_ecs::define_label;
// Defines `trait MyNewLabelTrait` and `static MY_NEW_LABEL_TRAIT_INTERNER`.
// You don’t need to use the interner for anything; just give it a unique name.
define_label!(
    /// Documentation of label trait
    MyNewLabelTrait,
);

/// A new label type implementing the new label trait.
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct MyLabel;

impl MyNewLabelTrait for MyLabel {
    // Implementations of the trait must implement the `dyn_clone()` method in this way
    // to enable cloning the trait object because `Clone` is not `dyn` compatible.
    fn dyn_clone(&self) -> Box<dyn MyNewLabelTrait> {
        Box::new(self.clone())
    }
}

assert_eq!(MyLabel.intern(), MyLabel.intern());

# use bevy_ecs::define_label;
define_label!(
    /// Documentation of another label trait
    MyNewExtendedLabelTrait,
    extra_methods: {
        // Extra methods for the trait can be defined here
        fn additional_method(&self) -> i32;
    },
    extra_methods_impl: {
        // Implementation of the extra methods for Interned<dyn MyNewExtendedLabelTrait>,
        // which should usually forward to the contained value.
        fn additional_method(&self) -> i32 {
            (**self).additional_method()
        }
    }
);

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct MyLabel;

impl MyNewExtendedLabelTrait for MyLabel {
    fn dyn_clone(&self) -> Box<dyn MyNewExtendedLabelTrait> {
        Box::new(self.clone())
    }

    fn additional_method(&self) -> i32 {
        42
    }
}

let interned_label = MyLabel.intern();
assert_eq!(interned_label.additional_method(), 42);

# use bevy_ecs::define_label;
define_label!(Team);

macro_rules! define_team {
    ($name:ident) => {
        #[derive(Clone, Debug, Eq, Hash, PartialEq)]
        pub struct $name;

        impl Team for $name {
            fn dyn_clone(&self) -> Box<dyn Team> {
                Box::new(self.clone())
            }
        }
    }
}

define_team!(Home);
define_team!(Away);

assert_eq!(Home.intern(), Home.intern());
assert_ne!(Home.intern(), Away.intern());

use bevy_ecs::prelude::*;
use bevy_ecs::entity::EntityHashSet;

#[derive(Component)]
struct MyTrackedComponent;

#[derive(Resource, Default)]
struct TrackedEntities(EntityHashSet);

let mut world = World::new();
world.init_resource::<TrackedEntities>();

// No entities with `MyTrackedComponent` have been added yet, so we can safely add component hooks
let mut tracked_component_query = world.query::<&MyTrackedComponent>();
assert!(tracked_component_query.iter(&world).next().is_none());

world.register_component_hooks::<MyTrackedComponent>().on_add(|mut world, context| {
   let mut tracked_entities = world.resource_mut::<TrackedEntities>();
  tracked_entities.0.insert(context.entity);
});

world.register_component_hooks::<MyTrackedComponent>().on_remove(|mut world, context| {
  let mut tracked_entities = world.resource_mut::<TrackedEntities>();
  tracked_entities.0.remove(&context.entity);
});

let entity = world.spawn(MyTrackedComponent).id();
let tracked_entities = world.resource::<TrackedEntities>();
assert!(tracked_entities.0.contains(&entity));

world.despawn(entity);
let tracked_entities = world.resource::<TrackedEntities>();
assert!(!tracked_entities.0.contains(&entity));

